-- 4) GOVERNORATES
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
    @egypt_id,'governorate',s.code,s.name_ar,s.name_en,'EG',1,
    JSON_OBJECT(
      'level',1,
      'geo',JSON_OBJECT('lat',s.latitude,'lon',s.longitude),
      'source','Open Admin Data',
      'source_updated','2026-09-08'
    ),
    NOW(),NOW()
FROM tmp_foodex_egypt_geo_seed s
WHERE s.level_no=1
ORDER BY s.code;

-- 5) DISTRICTS / MARKAZ
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
    p.id,s.node_type,s.code,s.name_ar,s.name_en,'EG',1,
    JSON_OBJECT(
      'level',2,
      'geo',JSON_OBJECT('lat',s.latitude,'lon',s.longitude),
      'source','Open Admin Data',
      'source_updated','2026-09-08'
    ),
    NOW(),NOW()
FROM tmp_foodex_egypt_geo_seed s
INNER JOIN geography_nodes p
    ON p.country_code='EG'
   AND p.type='governorate'
   AND p.code=s.parent_code
WHERE s.level_no=2
ORDER BY s.code;

-- 6) AREAS / SHIYAKHAS / VILLAGES
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
    p.id,'area',s.code,s.name_ar,s.name_en,'EG',1,
    JSON_OBJECT(
      'level',3,
      'geo',JSON_OBJECT('lat',s.latitude,'lon',s.longitude),
      'source','Open Admin Data',
      'source_updated','2026-09-08'
    ),
    NOW(),NOW()
FROM tmp_foodex_egypt_geo_seed s
INNER JOIN geography_nodes p
    ON p.country_code='EG'
   AND p.type IN ('district','markaz')
   AND p.code=s.parent_code
WHERE s.level_no=3
ORDER BY s.code;

-- 7) ROOT TERRITORY: EGYPT
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,service_calendar,
 tags,capabilities,notes,created_at,updated_at)
VALUES
('EG-COUNTRY','مصر','Egypt',@egypt_id,NULL,NULL,NULL,NULL,
 'active',100,NOW(),NULL,NULL,
 JSON_ARRAY('egypt','food-van','country'),
 JSON_OBJECT('van',TRUE,'visits',TRUE,'routing',TRUE,'orders',TRUE,'collections',TRUE),
 'FOODEX Egypt root service territory',NOW(),NOW());

-- 8) ALL 27 GOVERNORATES AS SERVICE TERRITORIES
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,service_calendar,
 tags,capabilities,notes,created_at,updated_at)
SELECT
    CONCAT('EG-GOV-',g.code),g.name_ar,g.name_en,@egypt_id,g.id,NULL,NULL,NULL,
    'active',200,NOW(),NULL,NULL,
    JSON_ARRAY('egypt','food-van','governorate'),
    JSON_OBJECT(
      'van',TRUE,'visits',TRUE,'routing',TRUE,'orders',TRUE,'collections',TRUE,
      'delta',IF(g.code IN ('EG02','EG18','EG12','EG11','EG13','EG14','EG15','EG16','EG17'),TRUE,FALSE)
    ),
    'FOODEX Egypt governorate service territory',
    NOW(),NOW()
FROM geography_nodes g
WHERE g.country_code='EG' AND g.type='governorate' AND g.is_active=1;

-- 9) DELTA DISTRICT / MARKAZ TERRITORIES
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,service_calendar,
 tags,capabilities,notes,created_at,updated_at)
SELECT
    CONCAT('EG-DIST-',d.code),d.name_ar,d.name_en,@egypt_id,g.id,NULL,d.id,NULL,
    'active',300,NOW(),NULL,NULL,
    JSON_ARRAY('egypt','delta','food-van','district'),
    JSON_OBJECT(
      'van',TRUE,'visits',TRUE,'routing',TRUE,'orders',TRUE,'collections',TRUE,
      'delta',TRUE,'district_node_id',d.id
    ),
    CONCAT('FOODEX Van Delta district under ',g.name_en),
    NOW(),NOW()
FROM geography_nodes d
INNER JOIN geography_nodes g
    ON g.id=d.parent_id
   AND g.country_code='EG'
   AND g.type='governorate'
WHERE d.country_code='EG'
  AND d.type IN ('district','markaz')
  AND d.is_active=1
  AND g.code IN ('EG02','EG18','EG12','EG11','EG13','EG14','EG15','EG16','EG17');

-- 10) EVERY DELTA LEAF AREA AS AN ACTIVE SERVICE TERRITORY
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,service_calendar,
 tags,capabilities,notes,created_at,updated_at)
SELECT
    CONCAT('EG-AREA-',a.code),a.name_ar,a.name_en,@egypt_id,g.id,NULL,d.id,NULL,
    'active',400,NOW(),NULL,NULL,
    JSON_ARRAY('egypt','delta','food-van','area',a.code),
    JSON_OBJECT(
      'van',TRUE,'visits',TRUE,'routing',TRUE,'orders',TRUE,'collections',TRUE,
      'delta',TRUE,
      'area_node_id',a.id,
      'area_code',a.code,
      'district_node_id',d.id,
      'governorate_node_id',g.id
    ),
    CONCAT('FOODEX Van Delta service area: ',a.name_en,' / ',d.name_en,' / ',g.name_en),
    NOW(),NOW()
FROM geography_nodes a
INNER JOIN geography_nodes d
    ON d.id=a.parent_id
   AND d.country_code='EG'
   AND d.type IN ('district','markaz')
INNER JOIN geography_nodes g
    ON g.id=d.parent_id
   AND g.country_code='EG'
   AND g.type='governorate'
WHERE a.country_code='EG'
  AND a.type='area'
  AND a.is_active=1
  AND d.is_active=1
  AND g.is_active=1
  AND g.code IN ('EG02','EG18','EG12','EG11','EG13','EG14','EG15','EG16','EG17');

-- 11) MAP DISPLAY POINT FOR EVERY DELTA AREA
-- These are real source coordinates, not fabricated geometry.
-- is_active=0 keeps them OUT of automatic point-in-polygon routing.
INSERT INTO territory_geometries
(service_territory_id,geometry_type,geojson,min_lat,max_lat,min_lng,max_lng,
 version,is_active,effective_from,effective_until,created_by,created_at,updated_at)
SELECT
    st.id,
    'Point',
    JSON_OBJECT(
      'type','Point',
      'coordinates',JSON_ARRAY(
        CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lon')) AS DECIMAL(10,7)),
        CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lat')) AS DECIMAL(10,7))
      )
    ),
    CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lat')) AS DECIMAL(10,7)),
    CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lat')) AS DECIMAL(10,7)),
    CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lon')) AS DECIMAL(10,7)),
    CAST(JSON_UNQUOTE(JSON_EXTRACT(a.metadata,'$.geo.lon')) AS DECIMAL(10,7)),
    1,0,NULL,NULL,NULL,NOW(),NOW()
FROM geography_nodes a
INNER JOIN geography_nodes d
    ON d.id=a.parent_id AND d.type IN ('district','markaz')
INNER JOIN geography_nodes g
    ON g.id=d.parent_id AND g.type='governorate'
INNER JOIN service_territories st
    ON st.code=CONCAT('EG-AREA-',a.code)
WHERE a.country_code='EG'
  AND a.type='area'
  AND a.is_active=1
  AND g.code IN ('EG02','EG18','EG12','EG11','EG13','EG14','EG15','EG16','EG17')
  AND JSON_EXTRACT(a.metadata,'$.geo.lat') IS NOT NULL
  AND JSON_EXTRACT(a.metadata,'$.geo.lon') IS NOT NULL;

DROP TEMPORARY TABLE IF EXISTS tmp_foodex_egypt_geo_seed;

COMMIT;

SET SQL_SAFE_UPDATES = @OLD_SQL_SAFE_UPDATES;
SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;

-- ============================================================
-- FINAL VERIFICATION
-- Expected geography: 1 / 27 / 365 / 5716
-- Expected Delta detailed service: 141 districts + 2942 areas
-- Expected visible area points: 2942
-- ============================================================

SELECT
    SUM(type='country') AS countries,
    SUM(type='governorate') AS governorates,
    SUM(type IN ('district','markaz')) AS districts_markaz,
    SUM(type='area') AS areas
FROM geography_nodes
WHERE country_code='EG';

SELECT
    SUM(code='EG-COUNTRY') AS country_territories,
    SUM(code LIKE 'EG-GOV-%') AS governorate_territories,
    SUM(code LIKE 'EG-DIST-%') AS delta_district_territories,
    SUM(code LIKE 'EG-AREA-%') AS delta_area_territories
FROM service_territories;

SELECT
    COUNT(DISTINCT st.id) AS delta_service_areas,
    COUNT(DISTINCT tg.service_territory_id) AS visible_on_map,
    COUNT(DISTINCT st.id)-COUNT(DISTINCT tg.service_territory_id) AS missing_map_geometry
FROM service_territories st
LEFT JOIN territory_geometries tg
    ON tg.service_territory_id=st.id
   AND tg.geometry_type='Point'
WHERE st.code LIKE 'EG-AREA-%';

SELECT
    g.name_ar AS governorate,
    COUNT(DISTINCT st.id) AS service_areas,
    COUNT(DISTINCT tg.service_territory_id) AS visible_points
FROM service_territories st
INNER JOIN geography_nodes g
    ON g.id=st.governorate_node_id
LEFT JOIN territory_geometries tg
    ON tg.service_territory_id=st.id
   AND tg.geometry_type='Point'
WHERE st.code LIKE 'EG-AREA-%'
GROUP BY g.id,g.name_ar
ORDER BY g.name_ar;
